using EddaStore.Models.Coupons; using EddaStore.Models.ViewModels.Admin.Coupons; using EddaStore.Services.Interfaces; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace EddaStore.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="Admin")]
public class CouponsController(ICouponService service):Controller { public async Task<IActionResult>Index(CancellationToken ct)=>View(await service.GetAllAsync(ct)); public IActionResult Create()=>View("Form",new CouponEditViewModel()); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult>Create(CouponEditViewModel m,CancellationToken ct){if(!ModelState.IsValid)return View("Form",m);try{await service.CreateAsync(Map(m),ct);TempData["Success"]="تمت إضافة الكوبون.";return RedirectToAction(nameof(Index));}catch(ArgumentException e){ModelState.AddModelError("",e.Message);return View("Form",m);}}public async Task<IActionResult>Edit(Guid id,CancellationToken ct){var x=await service.GetAsync(id,ct);return x is null?NotFound():View("Form",Map(x));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(Guid id,CouponEditViewModel m,CancellationToken ct){if(id!=m.Id)return BadRequest();if(!ModelState.IsValid)return View("Form",m);try{await service.UpdateAsync(Map(m),ct);TempData["Success"]="تم تعديل الكوبون.";return RedirectToAction(nameof(Index));}catch(KeyNotFoundException){return NotFound();}catch(ArgumentException e){ModelState.AddModelError("",e.Message);return View("Form",m);}}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){try{await service.DeleteAsync(id,ct);TempData["Success"]="تم حذف الكوبون.";}catch(KeyNotFoundException){return NotFound();}return RedirectToAction(nameof(Index));}private static Coupon Map(CouponEditViewModel x)=>new(){Id=x.Id,Code=x.Code,Description=x.Description,DiscountType=x.DiscountType,DiscountValue=x.DiscountValue,MinimumOrderAmount=x.MinimumOrderAmount,MaximumDiscountAmount=x.MaximumDiscountAmount,UsageLimit=x.UsageLimit,StartsAt=x.StartsAt,ExpiresAt=x.ExpiresAt,IsActive=x.IsActive};private static CouponEditViewModel Map(Coupon x)=>new(){Id=x.Id,Code=x.Code,Description=x.Description,DiscountType=x.DiscountType,DiscountValue=x.DiscountValue,MinimumOrderAmount=x.MinimumOrderAmount,MaximumDiscountAmount=x.MaximumDiscountAmount,UsageLimit=x.UsageLimit,StartsAt=x.StartsAt,ExpiresAt=x.ExpiresAt,IsActive=x.IsActive};}
